// Table-driven acceptance. Two fresh candidate sessions and the stock control.
// Expects are the literals in accept_table_j1.json. This file does not compute them.
// A failed assertion stops the run with ok:false.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_runner_j1.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { base64Bytes } from '../../om-emu/emu/src/util/bytes.mjs';
import { runZone } from './zone_session_j1.mjs';
import { applyStep, capture } from './observe_j1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_runner_j1.mjs om-emu\n');
  process.exit(2);
}

const table = JSON.parse(readFileSync(resolve('work/scripts/accept_table_j1.json'), 'utf8'));
const lines = [];
let stopped = false;
const emit = (row) => {
  const text = JSON.stringify(row);
  lines.push(text);
  console.log(text);
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(resolve('work/out/accept-j1.jsonl'), lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
const USE_RE = /use\('([^']+)'\)/g;

function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}

function shaFile(file) {
  const data = readFileSync(file);
  return { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}

function moduleInventory() {
  const seeds = [
    resolve('work/scripts/accept_runner_j1.mjs'),
    resolve('work/scripts/observe_j1.mjs'),
    resolve('work/scripts/zone_session_j1.mjs'),
    resolve('om-emu/emu/src/util/bytes.mjs'),
  ];
  const zoneText = readFileSync(resolve('work/scripts/zone_session_j1.mjs'), 'utf8');
  USE_RE.lastIndex = 0;
  let found;
  while ((found = USE_RE.exec(zoneText))) seeds.push(resolve('om-emu/emu', found[1]));
  const seen = new Map();
  const queue = [...seeds];
  while (queue.length) {
    const file = queue.pop();
    if (seen.has(file) || !existsSync(file)) continue;
    const data = readFileSync(file);
    seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
    const text = data.toString('utf8');
    IMPORT_RE.lastIndex = 0;
    let match;
    while ((match = IMPORT_RE.exec(text))) {
      const next = resolveSpec(file, match[1]);
      if (next && !seen.has(next)) queue.push(next);
    }
  }
  const resources = [
    'inputs/00_0100_50000020.decoded.bin',
    'inputs/02_0106_458c0020.decoded.bin',
    'ref/tasks/T3a-afon-zone-row/run-20261118-053855/work/out/overlay-changed-bytes.csv',
    'ref/tasks/T3i-afon-zone-acceptance/run-20261118-123315/work/out/overlay-changed-bytes.csv',
    'work/scripts/accept_table_j1.json',
  ].filter((path) => existsSync(resolve(path))).map((path) => ({ path, ...shaFile(resolve(path)) }));
  const modules = [...seen.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([file, rec]) => ({
    path: file.replaceAll('\\', '/'),
    sha256: rec.sha256,
    bytes: rec.bytes,
  }));
  return { modules, resources };
}

function wantOf(step, role) {
  const rb = step.expect.readback;
  const control = role === 'control';
  return {
    title: step.expect.title,
    highlight: step.expect.highlight,
    invariant: step.expect.invariant,
    readback: {
      profile: control ? rb.profileControl : rb.profile,
      profileCached: control ? rb.profileCachedControl : rb.profileCached,
      k90a1: rb.k90a1,
      screen: rb.screen,
      slotValue: rb.slotValue,
      helpId: rb.helpId,
      glyph: control ? (rb.glyphControl ?? null) : rb.glyph,
      saves: rb.saves ?? null,
      cells: rb.cells ?? null,
    },
  };
}

function judge(step, got, role, previous, controlGot) {
  const want = wantOf(step, role);
  const rb = want.readback;
  const problems = [];
  if (got.title !== want.title) problems.push('title');
  if (got.highlight !== want.highlight) problems.push('highlight');
  if (got.screen !== rb.screen) problems.push('screen');
  if (got.profile !== rb.profile) problems.push('profile');
  if (got.profileCached !== rb.profileCached) problems.push('profileCached');
  if (!same(got.invariant.k90a1, rb.k90a1)) problems.push('k90a1');
  if (got.slotValue !== rb.slotValue) problems.push('slotValue');
  if (got.helpId !== rb.helpId) problems.push('helpId');
  if (!same(got.glyph, rb.glyph)) problems.push('glyph');
  if (rb.saves != null && got.saves !== rb.saves) problems.push('saves');
  if (rb.cells && !same(got.invariant, rb.cells)) problems.push('cells');
  if (step.expect.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
  let controlSame = null;
  if (controlGot) {
    controlSame = got.title === controlGot.title
      && got.highlight === controlGot.highlight
      && got.screen === controlGot.screen
      && same(got.invariant, controlGot.invariant);
    if (!controlSame) problems.push('control');
  }
  return { pass: problems.length === 0, problems, want };
}

const controlGot = new Map();

function record(session, role, step, got, previous) {
  const controlRow = step.controlStep ? controlGot.get(step.controlStep) : null;
  const cellRow = step.cellControlStep ? controlGot.get(step.cellControlStep) : null;
  const judged = judge(step, got, role, previous, role === 'candidate' ? controlRow : null);
  if (cellRow && !same(got.invariant, cellRow.invariant)) {
    judged.pass = false;
    judged.problems.push('control-cells');
  }
  const row = {
    session,
    id: step.id,
    key: step.key,
    action: step.action,
    pass: judged.pass,
    problems: judged.problems,
    expected: judged.want,
    actual: {
      title: got.title,
      highlight: got.highlight,
      screen: got.screen,
      profile: got.profile,
      profileCached: got.profileCached,
      k90a1: got.invariant.k90a1,
      slotValue: got.slotValue,
      helpId: got.helpId,
      glyph: got.glyph,
      saves: got.saves ?? null,
      cells: got.invariant,
      screenshot: got.screenshot,
    },
    screenshot: got.screenshot,
    controlStep: step.controlStep,
    controlSame: role === 'candidate' && step.controlStep ? judged.problems.includes('control') === false : null,
  };
  emit(row);
  if (role === 'control') controlGot.set(step.id, got);
  return judged.pass;
}

async function runLane(name, role, lane, nvramPath, { page28 = false, canonical = false } = {}) {
  const steps = table.filter((step) => step.lane === lane && (role === 'candidate' || step.shared));
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-j1-' + name + '.jsonl',
    tag: 'accept-j1-' + name,
    candidate: role === 'candidate',
    help: true,
    rowLabel: true,
    page28,
    canonical,
    nvramPath,
    explanation: role === 'candidate'
      ? 'T3j candidate ' + name + '. T3i final configuration: H, the ten-record help list, and the kind-4 label. Role: behaviour.'
      : 'T3j stock control ' + name + '. Shared keys only.',
    change: role === 'candidate' ? 'T3i final configuration' : 'none',
    async drive(ctx) {
      ctx.takeFaces();
      let previous = null;
      for (const step of steps) {
        const got = step.action === 'reopen' ? capture(ctx, step.id) : await applyStep(ctx, step);
        const ok = record(name, role, step, got, previous);
        previous = got.invariant;
        if (!ok) throw new Error('assertion failed at ' + name + ' ' + step.id);
      }
    },
  });
  if (!result.ok) {
    stopped = true;
    emit({ record: 'session-failed', session: name, error: result.failed });
  }
  return result.ok;
}

function storeBytes(file) {
  const doc = JSON.parse(readFileSync(resolve(file), 'utf8'));
  return {
    M: Buffer.from(base64Bytes(doc.M)),
    E: Buffer.from(base64Bytes(doc.E)),
  };
}

function runStoreSteps() {
  const step = table.find((item) => item.id === 'store-compare');
  const control = storeBytes('work/out/nvram-j1-control.json');
  const actual = { mBytes: control.M.length, eBytes: control.E.length };
  let pass = control.M.length === step.expect.readback.mBytes && control.E.length === step.expect.readback.eBytes;
  for (const who of ['c1', 'c2']) {
    const store = storeBytes('work/out/nvram-j1-' + who + '.json');
    const sameM = control.M.equals(store.M);
    const sameE = control.E.equals(store.E);
    actual[who] = { sameM, sameE, mBytes: store.M.length, eBytes: store.E.length };
    if (!sameM || !sameE) pass = false;
  }
  emit({
    session: 'stores',
    id: step.id,
    key: null,
    action: step.action,
    pass,
    problems: pass ? [] : ['store'],
    expected: { sameM: true, sameE: true, mBytes: step.expect.readback.mBytes, eBytes: step.expect.readback.eBytes },
    actual,
    screenshot: null,
    controlStep: null,
  });
  if (!pass) stopped = true;
  const overlayStep = table.find((item) => item.id === 'overlay-compare');
  const ours = readFileSync(resolve('work/out/overlay-changed-bytes.csv'));
  const t3i = readFileSync(resolve('ref/tasks/T3i-afon-zone-acceptance/run-20261118-123315/work/out/overlay-changed-bytes.csv'));
  const same = ours.equals(t3i);
  const overlayPass = same && ours.length === overlayStep.expect.readback.bytes;
  emit({
    session: 'overlay',
    id: overlayStep.id,
    key: null,
    action: overlayStep.action,
    pass: overlayPass,
    problems: overlayPass ? [] : ['overlay'],
    expected: { same: true, bytes: overlayStep.expect.readback.bytes },
    actual: { same, bytes: ours.length, t3iBytes: t3i.length },
    screenshot: null,
    controlStep: null,
    note: 'Byte comparison with T3i overlay-changed-bytes.csv. A difference is a configuration deviation.',
  });
  if (!overlayPass) stopped = true;
}

const inventory = moduleInventory();
writeFileSync(resolve('work/out/import-inventory-j1.json'), JSON.stringify({
  note: 'SHA-256 taken before the acceptance sessions start.',
  hashed: 'execution',
  ...inventory,
}, null, 2) + '\n');
emit({
  record: 'import-inventory',
  hashed: 'execution',
  note: 'SHA-256 of every module walked from the runner, the capture module, the copied T3i session, and the modules that session imports, including their transitive static imports. Taken before the sessions start.',
  modules: inventory.modules.length,
  resources: inventory.resources.length,
});

try {
  const lanes = [
    ['control', 'control', 'main', 'work/out/nvram-j1-control.json', {}],
    ['p28-control', 'control', 'page28', 'work/out/nvram-j1-p28-control.json', { page28: true }],
    ['c1', 'candidate', 'main', 'work/out/nvram-j1-c1.json', { canonical: true }],
    ['c2', 'candidate', 'main', 'work/out/nvram-j1-c2.json', {}],
    ['p28-c1', 'candidate', 'page28', 'work/out/nvram-j1-p28-c1.json', { page28: true }],
    ['p28-c2', 'candidate', 'page28', 'work/out/nvram-j1-p28-c2.json', { page28: true }],
  ];
  for (const [name, role, lane, nvram, opts] of lanes) {
    if (stopped) break;
    await runLane(name, role, lane, nvram, opts);
  }
  if (!stopped) runStoreSteps();
  if (!stopped) {
    for (const who of ['c1', 'c2']) {
      if (stopped) break;
      await runLane('reopen-' + who, 'candidate', 'reopen', 'work/out/nvram-j1-' + who + '.json', {});
    }
  }
  emit({ record: 'done', ok: !stopped });
  if (stopped) process.exitCode = 1;
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
